diff --git a/src/domain/batches.js b/src/domain/batches.js
index ee14fde..ed24e12 100644
--- a/src/domain/batches.js
+++ b/src/domain/batches.js
@@ -20,7 +20,12 @@ export function getBatch(store, id) {

 // The order in which an item's batches are used up.
 function consumptionOrder(batches) {
-  return [...batches].sort((a, b) => b.receivedOn.localeCompare(a.receivedOn));
+  return [...batches].sort((a, b) => {
+    if (a.expires && b.expires && a.expires !== b.expires)
+      return a.expires.localeCompare(b.expires);
+    if (Boolean(a.expires) !== Boolean(b.expires)) return a.expires ? -1 : 1;
+    return a.receivedOn.localeCompare(b.receivedOn) || a.id - b.id;
+  });
 }

